def inside_out(x: str) -> str:
    words = x.split()
    if not words:
        return ""

    def transform(word):
        n = len(word)
        if n <= 2:
            return word

        chars = list(word)
        left = 0
        right = n - 1
        result = [''] * n

        while left < right:
            if (n % 2 == 1) and (left + 1 == right):
                mid = n // 2
                result[mid] = chars[mid]
                break

            result[left] = chars[right]
            result[right] = chars[left]
            left += 1
            right -= 1

        if n % 2 == 1:
            mid = n // 2
            if result[mid] == '':
                result[mid] = chars[mid]

        return "".join(result)

    transformed_words = [transform(word) for word in words]
    return " ".join(transformed_words)
